head.script:
scwin.getToday = function() {
    var date = new Date();
    var mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    return parseInt(mm);
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById('wq_uuid_1_calendar_selectbox_month_label').innerText == (scwin.getToday()+1+'월');
}
scwin.checkVal2 = function() {
    debugger;
    if (scwin.getToday() == 12)
        return (1 + '월') === WebSquare.wUnit.getDomById('wq_uuid_1_calendar_selectbox_month_label').innerText;
    else
        return (scwin.getToday() + 1 + '월') === WebSquare.wUnit.getDomById('wq_uuid_1_calendar_selectbox_month_label').innerText;
}

scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_calendar_selectbox_year_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_header_next_month').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 펼쳐놓은 SelectList 가 닫히면서 년 또는 월 이 이동된다. (그전버전에서는 1. 정리 처럼 SelectList 가 닫히지 않았음)
    //The year or month is shifted when the expanded SelectList is closed. (In previous versions, SelectList was not closed as in the first cleanup.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_1_calendar_selectbox_year_itemTable').css('visibility') == 'hidden'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
}
